 if(s.scenario==='conflict')return {kind:'conflict',text:'Источники противоречат друг другу: регламент разрешает передачу эксперту напрямую, а памятка требует согласования. Уточните актуальный порядок у владельца процесса.',refs:all.filter(m=>['expert','conflict'].includes(m.id)).map(m=>m.id)};
 const current=all.find(m=>m.id===context),last=(s.chats[context]||[]).findLast(m=>m.role==='assistant'&&m.kind==='explain'),previous=all.filter(m=>last?.refs?.includes(m.id));
 const ids=/статус|сообщ|ответ клиент/.test(q)?['status']:/регистр|карточк/.test(q)?['register','mistakes']:/эксперт|переда|сложн|обращен|клиент/.test(q)?['expert','mistakes']:[];
 let found=all.filter(m=>ids.includes(m.id));
 if(/не подходит|уточни/.test(q))return {kind:'clarify',text:'Что нужно: зарегистрировать обращение, передать сложный случай или сообщить статус?',refs:[]};
 if(/тренир/.test(q)){const ref=current||previous[0]||all.find(m=>m.id==='expert');return ref?{kind:'practice',text:ref.id==='status'?'Клиент ждёт ответа, но точный срок неизвестен. Что вы ему сообщите?':'Клиент пишет: «Всё ещё не работает». Вы уже проверили ситуацию по инструкции. Какие сведения передадите эксперту?',refs:[ref.id],attempt:null,hint:false}:none;}
 if(current){if(ids.length&&!ids.includes(current.id)||/зарплат|отпуск|вне курса|спектрометр/.test(q))return {kind:'expand',text:'В текущем материале нет ответа на этот вопрос. Искать в других доступных материалах?',refs:[]};found=[current];}
 else if(/ещё проще|еще проще|пример/.test(q)&&previous.length)found=previous;
 if(!found.length)return {...none,...(/объясни|проще|разобрать/.test(q)&&!ids.length?{kind:'prompt',text:isCourseContext(context)?'Какую тему или материал курса хотите разобрать?':'Что хотите понять? Напишите тему или вопрос — найду объяснение в доступных материалах.'}:{})};
 if(/пример/.test(q)){const ref=found[0],examples={status:'«Обращение передано эксперту. Проверка продолжается; точного срока пока нет. Сообщим вам, когда появится результат».',register:'«Не удаётся завершить заявку. Ожидаем сохранения. Проверили обязательные поля; ошибка сохраняется».',mistakes:'Вместо «не работает» укажите действие, ожидаемый результат и то, что уже проверили.'};return {kind:'example',text:'Учебный пример: '+(examples[ref.id]||'«Ошибка сохраняется после проверки по инструкции. Прилагаем описание и выполненные действия. Просим эксперта выяснить причину».')+' Это пример формулировки, а не новое правило компании.',refs:[ref.id]};}
